import { app, BrowserWindow } from 'electron';
import { mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
const url = process.argv.find((arg) => arg.startsWith('http://'));
app.setPath('userData', process.env.LINGXI_TEST_USER_DATA);
const delay = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
const output = process.env.LINGXI_VISUAL_OUTPUT;
mkdirSync(output, { recursive: true });
const checks = [], errors = [];
async function main() {
console.log('Side fixture: starting Electron');
await app.whenReady();
console.log('Side fixture: Electron ready');
const window = new BrowserWindow({ show: false, width: 1440, height: 940, useContentSize: true, webPreferences: { sandbox: true, backgroundThrottling: false } });
window.webContents.on('console-message', (details) => { if (details.level === 'error' || details.level === 3) errors.push(details.message); });
const run = (script) => window.webContents.executeJavaScript(script);
const wait = async (expression) => { const deadline = Date.now() + 10000; while (Date.now() < deadline) { if (await run(expression)) return; await delay(30); } throw new Error(`Timed out ${expression}\n${await run('document.body.innerText')}`); };
const check = async (name, expression) => { const passed = Boolean(await run(expression)); checks.push({ name, passed }); if (!passed) throw new Error(`Failed: ${name}`); };
const mainDraft = async (text) => { await run(`(() => { const input = document.querySelector('[contenteditable="true"]'); input.focus(); input.textContent = ${JSON.stringify(text)}; input.dispatchEvent(new InputEvent('input', { bubbles: true, inputType: 'insertText' })); })()`); await delay(40); };
const sideDraft = async (text) => { await run(`(() => { const input = document.querySelector('textarea[aria-label="Side Chat message"]'); Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, 'value').set.call(input, ${JSON.stringify(text)}); input.dispatchEvent(new Event('input', { bubbles: true })); })()`); await delay(40); };
try {
 for (const theme of ['light', 'dark']) {
  console.log('Side fixture: loading', theme);
  await window.loadURL(`${url}?theme=${theme}`);
  console.log('Side fixture: loaded', theme);
  await wait(`document.querySelector('[contenteditable="true"]') && document.body.innerText.includes('The main task is running')`);
  await run('sideFixture.state.delayAck = true');
  await mainDraft('/side What is a Side Chat?');
  await run(`document.querySelector('[aria-label="Send pending message"]').click()`);
  await check(`${theme}: create retains main draft before ack`, `document.querySelector('[contenteditable="true"]').textContent.includes('/side')`);
  await run(`document.querySelector('[aria-label="Send pending message"]').click()`);
  await wait(`document.querySelector('.side-chat-panel')?.innerText.includes('A Side Chat keeps')`);
  await wait(`!document.querySelector('[aria-label="Side Chat model"]').disabled && !document.querySelector('[aria-label="Side Chat reasoning effort"]').disabled`);
  await check(`${theme}: creation requests actual model controls and slash hydration`, `['list_models','get_conversation_controls','refresh_listings'].every(type => sideFixture.state.commands.some(command => command.sideId === 'side-1' && command.type === type))`);
  await check(`${theme}: no duplicate first send`, 'sideFixture.state.creates === 1 && sideFixture.state.promptSubmits === 0');
  await check(`${theme}: created ack clears main draft`, `document.querySelector('[contenteditable="true"]').textContent === ''`);
  await check(`${theme}: side transcript excludes parent context`, `!document.querySelector('.side-chat-panel').innerText.includes('The main task is running')`);
  await check(`${theme}: parent excludes side reply`, `!document.querySelector('.desktop-message-list-view').innerText.includes('A Side Chat keeps')`);
  await delay(100);
  writeFileSync(join(output, `side-${theme}-390.png`), (await window.webContents.capturePage()).toPNG());
  await sideDraft('keep this hidden draft');
  await run(`document.querySelector('[aria-label="Hide Side Chat"]').click()`);
  await check(`${theme}: hide retains reopen control`, `!document.querySelector('.side-chat-panel') && document.querySelector('[aria-label="Reopen Side Chat"]')`);
  await run(`document.querySelector('[aria-label="Reopen Side Chat"]').click()`);
  await check(`${theme}: reopen preserves draft`, `document.querySelector('textarea[aria-label="Side Chat message"]').value === 'keep this hidden draft'`);
  await sideDraft('/side nested is forbidden');
  await run(`document.querySelector('[aria-label="Send Side Chat message"]').click()`);
  await wait(`document.querySelector('.side-chat-notice')?.innerText.includes('not allowed')`);
  await check(`${theme}: failed input retains draft`, `document.querySelector('textarea[aria-label="Side Chat message"]').value === '/side nested is forbidden'`);
  await sideDraft('new successful side question');
  await run(`document.querySelector('[aria-label="Send Side Chat message"]').click()`);
  await check(`${theme}: side draft retained until ack`, `document.querySelector('textarea[aria-label="Side Chat message"]').value === 'new successful side question'`);
  await wait(`document.querySelector('textarea[aria-label="Side Chat message"]').value === ''`);
  await run(`document.querySelector('[aria-label="New Side Chat"]').click()`);
  await wait(`document.querySelector('[aria-label="Select Side Chat"]').options.length === 2`);
  await check(`${theme}: multiple sides selectable`, `document.querySelector('[aria-label="Select Side Chat"]').value === 'side-2'`);
  await sideDraft('prompt admitted during picker hydration');
  await run(`document.querySelector('[aria-label="Send Side Chat message"]').click()`);
  await wait(`document.querySelector('textarea[aria-label="Side Chat message"]').value === ''`);
  await check(`${theme}: hydration does not mute a new prompt`, `document.querySelector('.side-chat-panel').innerText.includes('prompt admitted during picker hydration')`);

  await run(`(() => { const select = document.querySelector('[aria-label="Select Side Chat"]'); select.value = 'side-1'; select.dispatchEvent(new Event('change', { bubbles: true })); })()`);
  await check(`${theme}: previous side timeline retained`, `document.querySelector('.side-chat-panel').innerText.includes('new successful side question')`);
  await run('sideFixture.state.holdNextTurn = true');
  await sideDraft('a real admitted turn to cancel');
  await run(`document.querySelector('[aria-label="Send Side Chat message"]').click()`);
  await wait(`document.querySelector('[aria-label="Stop Side Chat"]')`);
  await run(`document.querySelector('[aria-label="Stop Side Chat"]').click()`);
  await wait(`document.querySelector('[aria-label="Send Side Chat message"]')`);
  await sideDraft('send after cancel acknowledgement');
  await run(`document.querySelector('[aria-label="Send Side Chat message"]').click()`);
  await wait(`document.querySelector('textarea[aria-label="Side Chat message"]').value === ''`);
  await check(`${theme}: cancel ack permits the next prompt without a turn-start shim`, `document.querySelector('.side-chat-panel').innerText.includes('send after cancel acknowledgement')`);
  await run('sideFixture.state.commands = []; sideFixture.reconnect()');
  await wait(`['list_models','get_conversation_controls','refresh_listings'].every(type => sideFixture.state.commands.some(command => command.sideId === 'side-1' && command.type === type))`);
  await wait(`!document.querySelector('[aria-label="Side Chat reasoning effort"]').disabled`);
  await run('sideFixture.state.commands = []');
  await run(`(() => { const select = document.querySelector('[aria-label="Side Chat model"]'); select.value = 'openai/gpt-6-sol'; select.dispatchEvent(new Event('change', { bubbles: true })); })()`);
  await wait(`sideFixture.state.commands.some(command => command.type === 'set_model') && sideFixture.state.commands.some(command => command.type === 'get_conversation_controls')`);
  await check(`${theme}: model change refreshes side controls`, `document.querySelector('[aria-label="Side Chat model"]').value === 'openai/gpt-6-sol'`);
  await check(`${theme}: reconnect rehydrates model and controls`, `!document.querySelector('[aria-label="Side Chat model"]').disabled`);
  await check(`${theme}: side stop leaves parent running`, `document.querySelector('[aria-label="Send pending message"]') !== null`);
  await run(`(() => { for (let i = 0; i < 18; i++) { sideFixture.inner('side-1', {type:'text_delta',text:'Long side transcript for independent scrolling.\\n\\n'}); sideFixture.inner('side-1', {type:'message_complete'}); } })()`);
  await delay(100);
  const geometry = await run(`(() => { const panel = document.querySelector('.side-chat-panel'); const stage = panel.querySelector('.desktop-stage'); const composer = panel.querySelector('.side-chat-composer'); const model = panel.querySelector('[aria-label="Side Chat model"]'); const effort = panel.querySelector('[aria-label="Side Chat reasoning effort"]'); const send = panel.querySelector('[aria-label="Send Side Chat message"]'); stage.scrollTop = 0; return { width: panel.getBoundingClientRect().width, composerTop: composer.getBoundingClientRect().top, stageBottom: stage.getBoundingClientRect().bottom, scrollable: stage.scrollHeight > stage.clientHeight, modelWidth: model.getBoundingClientRect().width, effortWidth: effort.getBoundingClientRect().width, sendVisible: send.getBoundingClientRect().right <= panel.getBoundingClientRect().right, labelsHidden: getComputedStyle(panel.querySelector('.side-chat-aux-label')).display === 'none' }; })()`);
  checks.push({ name: `${theme}: 390px independent scroll and fixed composer`, passed: geometry.width === 390 && geometry.scrollable && geometry.stageBottom <= geometry.composerTop && geometry.modelWidth > 80 && geometry.effortWidth > 45 && geometry.sendVisible && geometry.labelsHidden, geometry });
  await run(`(() => { const separator = document.querySelector('[aria-label="Resize Side Chat"]'); for(let i = 0; i < 6; i++) separator.dispatchEvent(new KeyboardEvent('keydown', { key:'ArrowRight', bubbles:true })); })()`);
  await delay(100);
  await check(`${theme}: minimum 320 keeps model effort send visible`, `(() => { const panel = document.querySelector('.side-chat-panel'); return panel.getBoundingClientRect().width === 320 && panel.querySelector('[aria-label="Side Chat model"]').getBoundingClientRect().width > 50 && panel.querySelector('[aria-label="Side Chat reasoning effort"]').getBoundingClientRect().width > 40 && panel.querySelector('[aria-label="Send Side Chat message"]').getBoundingClientRect().right <= panel.getBoundingClientRect().right; })()`);
  writeFileSync(join(output, `side-${theme}-320.png`), (await window.webContents.capturePage()).toPNG());
  await run(`sideFixture.state.failCleanup = true; document.querySelector('[aria-label="End Side Chat"]').click()`);
  await wait(`document.querySelector('.side-chat-notice')?.innerText.includes('Cleanup')`);
  await check(`${theme}: failed cleanup retains a read-only chat and enables retry`, `!document.querySelector('[aria-label="End Side Chat"]').disabled && document.querySelector('textarea[aria-label="Side Chat message"]').disabled && document.querySelector('[aria-label="End Side Chat"]').title.includes('Retry ending')`);
  await run(`sideFixture.state.failCleanup = false; document.querySelector('[aria-label="End Side Chat"]').click()`);
  await wait(`document.querySelector('[aria-label="Select Side Chat"]').options.length === 1`);
  await check(`${theme}: retry ends only the failed side and keeps the parent running`, `document.querySelector('[aria-label="Select Side Chat"]').value === 'side-2' && document.querySelector('[aria-label="Send pending message"]') !== null`);
  await run('sideFixture.state.rejectNext = true');
  await mainDraft('/side retain failed creation');
  await run(`document.querySelector('[aria-label="Send pending message"]').click()`);
  await delay(80);
  await check(`${theme}: failed creation preserves parent draft`, `document.querySelector('[contenteditable="true"]').textContent === '/side retain failed creation'`);
  await mainDraft('/side original creation text');
  await run(`document.querySelector('[aria-label="Send pending message"]').click()`);
  await mainDraft('/side newer typing');
  await delay(450);
  await check(`${theme}: newer parent draft survives successful creation ack`, `document.querySelector('[contenteditable="true"]').textContent === '/side newer typing'`);
  await check(`${theme}: duplicate creation ack retains side transcript`, `(() => { const selected = document.querySelector('[aria-label="Select Side Chat"]').value; sideFixture.emit({type:'side_chat_created',request_id:'old',side_id:selected}); return true; })()`);
  await delay(40);
  await check(`${theme}: side transcript survives duplicate ack`, `document.querySelector('.side-chat-panel').innerText.includes('original creation text')`);

  await mainDraft('/side explain ');
  await run(`(() => { const editor = document.querySelector('[contenteditable="true"]'); const token = document.createElement('a'); token.dataset.fileMention = 'src/app.ts'; token.contentEditable = 'false'; token.textContent = '@app.ts'; editor.append(token); editor.dispatchEvent(new InputEvent('input', { bubbles: true, inputType: 'insertText' })); sideFixture.state.beforeMentionCreates = sideFixture.state.creates; })()`);
  await run(`document.querySelector('[aria-label="Send pending message"]').click()`);
  await wait(`sideFixture.state.creates === sideFixture.state.beforeMentionCreates + 1 && document.querySelector('.side-chat-panel').innerText.includes('@app.ts')`);
  await check(`${theme}: rich-file mention creates side with refs`, `sideFixture.state.creationInputs.at(-1) === '@src/app.ts\\n\\nexplain' && document.querySelector('.side-chat-panel').innerText.includes('@app.ts') && document.querySelector('.side-chat-panel').innerText.includes('explain') && sideFixture.state.parentPrompts.length === 0`);
  await mainDraft('/sideways explain ');
  await run(`(() => { const editor = document.querySelector('[contenteditable="true"]'); const token = document.createElement('a'); token.dataset.fileMention = 'src/app.ts'; token.contentEditable = 'false'; token.textContent = '@app.ts'; editor.append(token); editor.dispatchEvent(new InputEvent('input', { bubbles: true, inputType: 'insertText' })); })()`);
  await run(`document.querySelector('[aria-label="Send pending message"]').click()`);
  await wait(`sideFixture.state.parentPrompts.length === 1`);
  await check(`${theme}: sideways rich-file prompt stays parent`, `sideFixture.state.creates === sideFixture.state.beforeMentionCreates + 1 && sideFixture.state.parentPrompts[0].includes('/sideways explain') && sideFixture.state.parentPrompts[0].includes('@src/app.ts')`);

 }
} catch (error) { errors.push(String(error)); }
writeFileSync(join(output, 'checks.json'), JSON.stringify({ checks, errors }, null, 2));
window.destroy(); app.exit(errors.length || checks.some((check) => !check.passed) ? 1 : 0);
}
main().catch(error => { console.error(error); app.exit(1); });
